def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i <= n:
        if i == n:
            # End of line - add the current field
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            field = ''
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Doubled quote - represents a single quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        if i == n or line[i] == ',':
                            fields.append(field)
                            if i < n:
                                i += 1  # Skip the comma
                            else:
                                i = n + 1  # Mark end
                            break
                        else:
                            # Character after closing quote is not comma or end
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain a quote
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < n:
                i += 1  # Skip the comma

    return fields

